mapper.select:
/* buttle.apptpl.cmm.menu.mapper.MenuMapper.selectMenuByAuthLevel */ WITH RECURSIVE menu_tree AS ( SELECT m.cmpy_type_cd, m.menu_id, 1 AS menu_lvl FROM cdm_own.cmpt_cmpy_menu m WHERE m.up_menu_id IS NULL OR m.up_menu_id = '' UNION ALL SELECT c.cmpy_type_cd, c.menu_id, p.menu_lvl + 1 FROM cdm_own.cmpt_cmpy_menu c INNER JOIN menu_tree p ON c.up_menu_id = p.menu_id AND c.cmpy_type_cd = p.cmpy_type_cd WHERE p.menu_lvl < 10 /* 데이터에 순환이 있어도 무한 재귀로 빠지지 않게 하는 안전장치 */ ) SELECT m.cmpy_type_cd, m.menu_id, m.menu_nm, m.url_addr AS tmplt_url_addr, m.npag_yn, m.up_menu_id, m.sort_sn, m.menu_use_yn, m.scrn_size, ma.authrt_cd, a.auth_nm AS authrt_nm, a.auth_dvcd AS authrt_se, COALESCE(t.menu_lvl, 1) AS menu_lvl FROM cdm_own.cmpt_cmpy_menu m INNER JOIN cdm_own.cmpt_cmpy_menu_authrt ma ON ma.cmpy_type_cd = m.cmpy_type_cd AND ma.menu_id = m.menu_id LEFT JOIN cdm_own.auth a ON a.auth_cd = ma.authrt_cd LEFT JOIN menu_tree t ON t.cmpy_type_cd = m.cmpy_type_cd AND t.menu_id = m.menu_id WHERE COALESCE(m.menu_use_yn, 'Y') = 'Y'
AND m.cmpy_type_cd = #{cmpyTypeCd}
AND ma.authrt_cd = #{authLvl}
ORDER BY COALESCE(t.menu_lvl, 1), m.sort_sn, m.menu_id
